#!/usr/bin/env bash
# Removes the HelmReleases that the operator replaces WITHOUT uninstalling their Helm releases (and therefore without
# deleting any workloads, CRDs or data). Old workloads are removed afterwards explicitly (runbook step).
# Method: suspend the HelmRelease, drop the Flux finalizer, delete the object. UNGEPRUEFT in the throwaway environment.
# Prerequisite: the Kustomizations that own them are suspended (flux suspend kustomization gardener pre-gardener addons yake).
# Stages: --stage=core (default) or --stage=extensions (the HelmReleases generated by gardener/extensions for catalog extensions,
# see operator/extensions/templates/_catalog.tpl; their ControllerRegistrations are adopted by the operator).
# Default is --dry-run. Usage: decouple-flux.sh --runtime-kubeconfig=<path> [--stage=core|extensions] [--apply]
set -euo pipefail
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
source "$SCRIPT_DIR/../lib.sh"
EXTRA_ARGS=()
usage() { sed -n '2,7p' "$0"; }
parse_common_args "$@"
require_runtime

STAGE=core
for a in "${EXTRA_ARGS[@]:-}"; do [[ "$a" == --stage=* ]] && STAGE="${a#*=}"; done
case "$STAGE" in
  core)
    REPLACED_HRS=(
      gardener-application gardener-runtime kube-apiserver etcd etcd-events
      dashboard-application dashboard-runtime terminal-controller-manager-application terminal-controller-manager-runtime
      ingress-nginx gardener-metrics-exporter-runtime gardener-metrics-exporter-application
    ) ;;
  extensions)
    REPO_ROOT="$(cd "$SCRIPT_DIR/../../.." && pwd)"
    REPLACED_HRS=()
    for k in $(grep -oE '^[a-z0-9-]+:$' "$REPO_ROOT/operator/extensions/templates/_catalog.tpl" | tr -d ':'); do
      for hr in "$k" "admission-$k-application" "admission-$k-runtime"; do REPLACED_HRS+=("$hr"); done
    done ;;
  gardenlet) REPLACED_HRS=(internal-gardenlet) ;;
  *) die "unknown stage $STAGE" ;;
esac

for k in gardener pre-gardener addons yake; do  # suspended Kustomizations are a prerequisite for both stages
  s="$(kr get kustomization "$k" -n flux-system -o jsonpath='{.spec.suspend}' 2>/dev/null || true)"
  [[ "$s" == true ]] || { $APPLY && die "Kustomization $k must be suspended first"; echo "[note] Kustomization $k is not suspended (required for --apply)"; }
done
confirm_apply

for hr in "${REPLACED_HRS[@]}"; do
  if ! kr get hr "$hr" -n flux-system >/dev/null 2>&1; then echo "skip $hr (not found)"; continue; fi
  echo "== $hr"
  mutate kr patch hr "$hr" -n flux-system --type=merge -p '{"spec":{"suspend":true}}'
  mutate kr patch hr "$hr" -n flux-system --type=merge -p '{"metadata":{"finalizers":null}}'
  mutate kr delete hr "$hr" -n flux-system --wait=false
done

if [[ "$STAGE" == core ]]; then
  # The addons chart installs the VPA CRDs (vpa.enabled). gardener-operator deploys and updates them itself (Gardener 1.139 needs
  # updateMode InPlaceOrRecreate, which the old CRD of the chart lacks). Keep the CRDs when `vpa.enabled: false` is set in addons-values.
  for crd in verticalpodautoscalers.autoscaling.k8s.io verticalpodautoscalercheckpoints.autoscaling.k8s.io; do
    if kr get crd "$crd" >/dev/null 2>&1; then
      echo "== CRD $crd: helm.sh/resource-policy=keep"
      mutate kr annotate crd "$crd" helm.sh/resource-policy=keep --overwrite
    fi
  done
fi

